import type { SVGProps } from 'react'

/**
 * Icons for the WeChat-style chrome.
 *
 * Where WeChat ships the glyph, the SVG is taken verbatim from the payloads
 * embedded in `Weixin.dll` (see `WechatIcons.tsx`, generated by
 * `.cache/wxsvg/gen_icons.py`) and re-exported below. Two glyphs are not from
 * that set: `MomentsTabIcon` is WeChat's design-system compass
 * (`.cache/wxres/tabBar_icons_outlined_discover.svg`), and `TelegramLogo` is the
 * third-party brand mark from Simple Icons (CC0). The brand mark is used for the
 * rail's 聊天 tab, the login card and the empty-pane watermark.
 */

type IconProps = SVGProps<SVGSVGElement> & { size?: number }

export {
  AddFriendIcon,
  CallBubbleIcon,
  CallIcon,
  ChevronDownIcon,
  ContactsTabIcon,
  CubeTabIcon,
  DeviceIcon,
  EmojiIcon,
  FolderIcon,
  MenuIcon,
  MicIcon,
  MoreIcon,
  NewGroupIcon,
  NoteIcon,
  PlusIcon,
  ScissorsIcon,
  SearchIcon,
  StickerCubeIcon,
} from './WechatIcons'

import { CallBubbleIcon } from './WechatIcons'

/** Header "voice / video call" entry: WeChat's own bubble glyph. */
export function CallMenuIcon(props: IconProps) {
  return <CallBubbleIcon {...props} />
}

/**
 * Side rail: 发现/朋友圈 — WeChat's compass. The geometry is the design-system
 * SVG (ring plus a rhombus needle), not a redraw, so the needle angle and the
 * ring weight match the client.
 */
export function MomentsTabIcon({ size = 24, ...rest }: IconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden="true"
      {...rest}
    >
      <path d="M12,20.8 C16.8601058,20.8 20.8,16.8601058 20.8,12 C20.8,7.1398942 16.8601058,3.2 12,3.2 C7.1398942,3.2 3.2,7.1398942 3.2,12 C3.2,16.8601058 7.1398942,20.8 12,20.8 Z M12,22 C6.4771525,22 2,17.5228475 2,12 C2,6.47771525 6.4771525,2 12,2 C17.5228475,2 22,6.47771525 22,12 C22,17.5228475 17.5228475,22 12,22 Z M11.1233556,11.1233556 L9.26736162,14.7326384 L12.8766444,12.8766444 L14.7326384,9.26736162 L11.1233556,11.1233556 Z M10.232233,10.232233 L16.1243501,7.20234187 C16.2678549,7.12854767 16.4381526,7.12854767 16.5816575,7.20234187 C16.8272333,7.32862381 16.9239401,7.63007409 16.7976581,7.87564991 L13.767767,13.767767 L7.87564991,16.7976581 C7.73214506,16.8714523 7.56184738,16.8714523 7.41834253,16.7976581 C7.17276672,16.6713762 7.07605992,16.3699259 7.20234187,16.1243501 L10.232233,10.232233 Z" />
    </svg>
  )
}

/**
 * Transcript "跳转到最新消息" pill: the double chevron WeChat draws at its left.
 *
 * Hand-drawn (the Weixin.dll payload manifest has no recoverable name→glyph map,
 * see `docs/UI-HANDOFF.md` §3) from the client's own pill: two round-capped
 * chevrons, ~15 × 7 px each, ~3 px apart, stroke ≈ 1.7 px.
 */
export function JumpToLatestIcon({ size = 14, ...rest }: IconProps) {
  return (
    <svg
      width={size}
      height={(size * 18) / 16}
      viewBox="0 0 16 18"
      fill="none"
      aria-hidden="true"
      focusable="false"
      {...rest}
    >
      <path
        d="M2.6 2.2 8 7.6 13.4 2.2"
        stroke="currentColor"
        strokeWidth="1.7"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <path
        d="M2.6 10.2 8 15.6 13.4 10.2"
        stroke="currentColor"
        strokeWidth="1.7"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

/**
 * Empty-chat watermark and login mark: the Telegram paper-plane roundel from
 * Simple Icons (<https://simpleicons.org/?q=telegram>, CC0 1.0), copied verbatim
 * and drawn with `currentColor`. The plane is a hole in the disc (subtracted
 * subpath), so the pane background shows through instead of being painted white.
 * The login card tints it WeChat green; the empty pane keeps its light grey.
 */
export function TelegramLogo({ size = 112, ...rest }: IconProps) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" aria-hidden="true" {...rest}>
      <path
        fill="currentColor"
        d="M11.944 0A12 12 0 0 0 0 12a12 12 0 0 0 12 12 12 12 0 0 0 12-12A12 12 0 0 0 12 0a12 12 0 0 0-.056 0zm4.962 7.224c.1-.002.321.023.465.14a.506.506 0 0 1 .171.325c.016.093.036.306.02.472-.18 1.898-.962 6.502-1.36 8.627-.168.9-.499 1.201-.82 1.23-.696.065-1.225-.46-1.9-.902-1.056-.693-1.653-1.124-2.678-1.8-1.185-.78-.417-1.21.258-1.91.177-.184 3.247-2.977 3.307-3.23.007-.032.014-.15-.056-.212s-.174-.041-.249-.024c-.106.024-1.793 1.14-5.061 3.345-.48.33-.913.49-1.302.48-.428-.008-1.252-.241-1.865-.44-.752-.245-1.349-.374-1.297-.789.027-.216.325-.437.893-.663 3.498-1.524 5.83-2.529 6.998-3.014 3.332-1.386 4.025-1.627 4.476-1.635z"
      />
    </svg>
  )
}
